## ---- 01: Refinance Incentive Specifications  (qmd line 287) --------------------------

# Three forms of incentive
spread_incentive <- function(c, r_ref) c - r_ref
ratio_incentive  <- function(c, r_ref) log(c / r_ref)
pv_incentive     <- function(c, r_ref, B, tau, dt = 1/12) {
  pmt_old <- B * (c * dt) / (1 - (1 + c * dt)^(-tau))
  pmt_new <- B * (r_ref * dt) / (1 - (1 + r_ref * dt)^(-tau))
  v_old <- sum(pmt_old / (1 + c * dt)^seq_len(tau))
  v_new <- sum(pmt_new / (1 + r_ref * dt)^seq_len(tau))
  (v_old - v_new) / B
}


## ---- 02: Arctan S-Curve  (qmd line 302) ----------------------------------------------

# Standard arctan refinance incentive curve
arctan_scurve <- function(I, a = 0.04, b = 0.20, c = 250, I0 = 0.005) {
  a + b * (atan(c * (I - I0)) / pi + 0.5)
}

library(ggplot2)
I_grid <- seq(-0.02, 0.04, by = 0.001)
ggplot(data.frame(incentive = I_grid, cpr = arctan_scurve(I_grid)),
       aes(incentive, cpr)) +
  geom_line() +
  labs(x = "Refi incentive", y = "Annualized CPR") +
  theme_minimal()


## ---- 03: Logistic Alternative  (qmd line 319) ----------------------------------------

logistic_scurve <- function(I, a = 0.04, b = 0.20, c = 200, I0 = 0.005) {
  a + (b - a) / (1 + exp(-c * (I - I0)))
}


## ---- 04: Heterogeneity-Based Prepay (Stanton-Style)  (qmd line 327) ------------------

# Population of borrowers with different transaction costs
n_borrowers <- 1000
costs <- rgamma(n_borrowers, shape = 2, scale = 0.005)
# Critical PV gain for each borrower
pv_gain <- 0.012   # 120 bp NPV gain from refinancing
prepay_fraction <- mean(costs < pv_gain)
prepay_fraction


## ---- 05: Burnout Adjustment  (qmd line 339) ------------------------------------------

# Multiplicative burnout factor
burnout_factor <- function(cumulative_incentive,
                            decay_rate = 50) {
  exp(-decay_rate * cumulative_incentive)
}

# Effective CPR
effective_cpr <- function(I, cum_I) {
  arctan_scurve(I) * burnout_factor(cum_I)
}


## ---- 06: Penalty-Adjusted Incentive  (qmd line 354) ----------------------------------

library(dplyr)   # for case_when()

# Adjust refi NPV for prepay penalty in years 1-3
penalty_schedule <- function(months_seasoned) {
  case_when(
    months_seasoned <= 12 ~ 0.05,
    months_seasoned <= 24 ~ 0.03,
    months_seasoned <= 36 ~ 0.01,
    TRUE                  ~ 0.00
  )
}

incentive_with_penalty <- function(c, r_ref, age) {
  spread_incentive(c, r_ref) - penalty_schedule(age)
}


